INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l06',3,2,6,'It Was Only a Movie','原来在拍电影','一般过去时 vs 过去进行时(叙事主干 vs 当时正在进行的背景·承载官方KS),外加否定前缀构词法(possible→impossible、aware→unaware、agree→disagree、legible→illegible、regular→irregular)与 with + 名词 + 分词/介词的伴随状况结构(with its headlights on / with masks over their faces),再带过去完成时铺垫更早的背景(原创承载 NCE3 L6 考点;原题材珠宝抢劫已按净化规则改为''剧组拍电影、店主误会''的无害喜剧)','市中心一条著名拱廊街上的高档店铺刚开门。这么早,拱廊街上几乎没人。开珠宝店的泰勒先生正欣赏他新布置的橱窗。两个店员从八点起就一直忙着,刚刚才弄完:钻石项链和戒指漂亮地摆在黑色天鹅绒衬底上。泰勒先生盯着橱窗看了几分钟,才退回店里。忽然,一辆大车顶灯亮着、喇叭长鸣,轰隆隆冲下拱廊街,正停在珠宝店门口。一人留在方向盘后,另两个脸上蒙着面罩的跳下车,动手砸橱窗。就在这时,泰勒先生正在楼上,压根没察觉附近藏着一支摄制组。他一口咬定是抢劫,便和店员们把椅子、烟灰缸、花瓶往窗外扔,家具满拱廊街乱飞!那几个“劫匪”爬回车里,车以惊人的速度开走。就在车要走时,泰勒先生冲了出去还在扔东西,直到一个年轻女子挥着手臂大喊:“停!这只是电影!”原来劫匪是演员,车是道具,这一切都是在拍电影。真是让人忍不住发笑——泰勒先生“英勇救店”成了片子里最好笑的一场戏。','{"q":"Listen and answer — What was really happening in the arcade?","options":["A movie was being filmed","A real robbery","A big fire","A street market"],"answer_index":0}'::jsonb,'{"title":"过去叙事 + 否定前缀 + with 伴随结构","intro":"①一般过去时讲“发生了什么”(a car roared in);过去进行时讲“当时正在进行、当背景”的动作(Mr. Taylor was admiring the display / the actors were smashing the window)。②否定前缀构词:给形容词/动词加 un-、im-、in-、dis-、il-、ir- 变反义——possible→impossible、aware→unaware、correct→incorrect、agree→disagree、legible→illegible、regular→irregular。③with + 名词 + 分词/介词/形容词,表示“某物怎样着”的伴随情况:with its headlights on、with its horn blaring、with masks over their faces。④更早的背景用过去完成时:had been working since eight、had been arranged。","table":{"headers":["点","用来讲","例子"],"rows":[["一般过去 vs 过去进行","发生的动作 vs 当时正在进行的背景","A car roared in while he was admiring the display."],["否定前缀 un-/im-/in-","加前缀变反义","possible→impossible, aware→unaware, correct→incorrect"],["否定前缀 dis-/il-/ir-","加前缀变反义","agree→disagree, legible→illegible, regular→irregular"],["with + 名词 + 分词/介词","伴随状况“某物怎样着”","with its horn blaring / with masks over their faces"]]},"specialRules":[{"rule":"选哪个否定前缀多半要背:im- 常用在 p/m 前(impossible, impolite);il- 用在 l 前(illegal, illegible);ir- 用在 r 前(irregular);其余多用 un-/in-/dis-。","mark":"im-/il-/ir-"},{"rule":"with 的伴随结构里,名词后面主动、正在进行用现在分词(with the engine running),被动、完成的状态用过去分词(with his arms folded),静止状态可用介词或形容词(with the lights on)。","mark":"with + n + doing/done"},{"rule":"美语“珠宝”拼 jewelry(英式 jewellery);“电影”说 movie(英式 film)。本课已按美语写。","mark":"jewelry / movie"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l06',1,NULL,'The expensive shops in a famous outdoor arcade downtown were just opening. At this early hour, the arcade was almost empty. Mr. Taylor, who owned a jewelry shop, was admiring his new window display.','市中心一条著名拱廊街上的高档店铺刚开门。这么早,拱廊街上几乎没人。开珠宝店的泰勒先生正欣赏他新布置的橱窗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l06',2,NULL,'His two assistants had been working busily since eight o''clock and had only just finished. Diamond necklaces and rings had been beautifully arranged on a background of black velvet. After gazing at the display for a few minutes, Mr. Taylor stepped back into his shop.','两个店员从八点起就一直忙着,刚刚才弄完:钻石项链和戒指漂亮地摆在黑色天鹅绒衬底上。泰勒先生盯着橱窗看了几分钟,才退回店里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l06',3,NULL,'The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade. It came to a stop right outside the jeweler''s. One man stayed at the wheel while two others, with masks over their faces, jumped out and began to smash the shop window with bright rubber bars.','忽然,一辆大车顶灯亮着、喇叭长鸣,轰隆隆冲下拱廊街,正停在珠宝店门口。一人留在方向盘后,另两个脸上蒙着面罩的跳下车,用亮色橡胶棒动手砸橱窗。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l06',4,NULL,'While this was going on, Mr. Taylor was upstairs, completely unaware that a film crew was hiding nearby. Sure that a raid was happening, he and his staff started throwing chairs, ashtrays, and vases out of the window. Furniture went flying into the arcade!','就在这时,泰勒先生正在楼上,压根没察觉附近藏着一支摄制组。他一口咬定是抢劫,便和店员们把椅子、烟灰缸、花瓶往窗外扔,家具满拱廊街乱飞!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l06',5,NULL,'The ''thieves'' scrambled back into the car, and it moved off at a fantastic speed. A young woman waved her arms and shouted, ''Stop! It''s only a movie!'' The robbers were actors, the car was a prop, and it had all been part of a film. Poor Mr. Taylor turned red, for his brave ''rescue'' was now the funniest scene in the movie.','那几个“劫匪”爬回车里,车以惊人的速度开走。一个年轻女子挥着手臂大喊:“停!这只是电影!”原来劫匪是演员,车是道具,这一切都是在拍电影。可怜的泰勒先生脸都红了——他“英勇救店”成了片子里最好笑的一场戏。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
