INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l06','come to a stop','',NULL,'/kʌm tuː ə stɑːp/','The car came to a stop outside the shop.','车在店门口停了下来。','The bus slowly came to a stop.','公交车慢慢停了下来。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l06','move off','',NULL,'/muːv ɔːf/','The car moved off at a fantastic speed.','车以惊人的速度开走了。','The train moved off just as we arrived.','我们刚到,火车就开走了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l06','at a fantastic speed','',NULL,'/æt ə fænˈtæstɪk spiːd/','It drove away at a fantastic speed.','它以惊人的速度开走了。','The runner crossed the line at a fantastic speed.','那名跑者以惊人的速度冲过终点。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l06','turn red','',NULL,'/tɜːrn red/','Poor Mr. Taylor turned red with embarrassment.','可怜的泰勒先生窘得脸都红了。','She turned red when everyone looked at her.','大家一看她,她就脸红了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp1','choice','{"stem":"\"When the car roared in, Mr. Taylor ___ his new window display.\"(当时正在做的背景:过去进行)","options":["has admired","admired","was admiring","admires"],"answer_index":2,"stem_cn":"车冲进来时,泰勒先生正在欣赏他新布置的橱窗。","explanation_cn":"“车冲进来”是那一刻发生的事,“正在欣赏橱窗”是当时正在进行、当背景的动作,用过去进行时。✓ he was admiring the display. ✗ admired:一般过去讲完成动作,这里要强调“正在”;✗ admires / has admired:时态不对。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp1','choice','{"stem":"\"While the two actors ___ the window, Mr. Taylor was upstairs.\"(持续的背景:过去进行)","options":["smash","were smashing","have smashed","smashed"],"answer_index":1,"stem_cn":"两个演员正砸橱窗时,泰勒先生在楼上。","explanation_cn":"“泰勒在楼上”的同时,演员“正砸着橱窗”是持续的背景动作,主语是复数,用 were + doing。✓ the actors were smashing the window. ✗ smashed:强调的是持续背景;✗ smash / have smashed:时态不对。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp1','choice','{"stem":"\"A large car suddenly ___ down the empty arcade.\"(突发、打断背景的动作:一般过去)","options":["roars","has roared","roared","was roaring"],"answer_index":2,"stem_cn":"一辆大车突然轰隆隆冲下空荡荡的拱廊街。","explanation_cn":"“突然冲下来”是打断安静、发生并完成的动作,用一般过去时。✓ a car suddenly roared down the arcade. ✗ was roaring:这里落点在“突然发生”这一下;✗ roars / has roared:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp2','choice','{"stem":"\"It was ___ to stop all the flying furniture.\"(“不可能的”,用哪个词)","options":["unpossible","inpossible","dispossible","impossible"],"answer_index":3,"stem_cn":"要挡住满天乱飞的家具是不可能的。","explanation_cn":"possible(可能的)的反义是 impossible,加前缀 im-(常用在 p 前)。✓ It was impossible to stop them. ✗ unpossible / dispossible / inpossible:都不是正确的构词。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp2','choice','{"stem":"\"Mr. Taylor was completely ___ that it was only a movie.\"(“没察觉的、不知道的”,用哪个词)","options":["inaware","disaware","unaware","imaware"],"answer_index":2,"stem_cn":"泰勒先生完全没察觉这只是在拍电影。","explanation_cn":"aware(察觉到的)的反义是 unaware,加前缀 un-。✓ He was unaware of the film crew. ✗ disaware / inaware / imaware:都不是正确的构词。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp2','choice','{"stem":"\"The first guess of a robbery was totally ___.\"(“不正确的”,用哪个词)","options":["uncorrect","incorrect","imcorrect","discorrect"],"answer_index":1,"stem_cn":"关于抢劫的第一个猜测完全不对。","explanation_cn":"correct(正确的)的反义是 incorrect,加前缀 in-。✓ The first guess was incorrect. ✗ uncorrect / discorrect / imcorrect:都不是正确的构词。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp3','choice','{"stem":"\"The two men began to ___ about who was to blame.\"(“意见不一致、不同意”,用哪个词)","options":["unagree","inagree","ilagree","disagree"],"answer_index":3,"stem_cn":"两个人开始为该怪谁而争执不下。","explanation_cn":"agree(同意)的反义是 disagree,加前缀 dis-。✓ The two men began to disagree. ✗ unagree / inagree / ilagree:都不是正确的构词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp3','choice','{"stem":"\"His messy handwriting on the note was almost ___.\"(“字迹难以辨认的”,用哪个词)","options":["dislegible","inlegible","illegible","unlegible"],"answer_index":2,"stem_cn":"他字条上潦草的字几乎认不出来。","explanation_cn":"legible(字迹清楚的)的反义是 illegible,加前缀 il-(用在 l 前)。✓ His handwriting was almost illegible. ✗ unlegible / dislegible / inlegible:都不是正确的构词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp3','choice','{"stem":"\"The old prop gun fired at ___ times, never the same way twice.\"(“不规则的、无规律的”,用哪个词)","options":["irregular","disregular","unregular","inregular"],"answer_index":0,"stem_cn":"那把道具枪毫无规律地响,每次都不一样。","explanation_cn":"regular(规则的)的反义是 irregular,加前缀 ir-(用在 r 前)。✓ It fired at irregular times. ✗ unregular / disregular / inregular:都不是正确的构词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp4','choice','{"stem":"\"The car came in with its horn ___ loudly.\"(with + 名词 + 现在分词:某物正在……)","options":["to blare","blared","blaring","blare"],"answer_index":2,"stem_cn":"那辆车开进来时喇叭大声响着。","explanation_cn":"with + 名词 + 现在分词,表示“某物正在……”的伴随情况;喇叭是自己在响,用现在分词 blaring。✓ with its horn blaring. ✗ blared / blare / to blare:都配不出这个伴随结构。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp4','choice','{"stem":"\"The actor stood there with his arms ___ across his chest.\"(with + 名词 + 过去分词:被……的状态)","options":["folded","fold","folding","folds"],"answer_index":0,"stem_cn":"那个演员站在那儿,双臂交叉抱在胸前。","explanation_cn":"with + 名词 + 过去分词,表示“某物被……的状态”;胳膊是“被交叉抱着”的状态,用过去分词 folded。✓ with his arms folded. ✗ folding / fold / folds:配不出“被交叉着”的状态。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp4','choice','{"stem":"\"She waited by the curb with the engine still ___.\"(with + 名词 + 现在分词:某物一直在……)","options":["run","to run","running","ran"],"answer_index":2,"stem_cn":"她在路边等着,发动机还开着。","explanation_cn":"with + 名词 + 现在分词,表示“某物一直在……”;发动机自己在转，用现在分词 running。✓ with the engine still running. ✗ run / ran / to run:配不出这个伴随结构。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp5','choice','{"stem":"\"The two assistants ___ since eight o''clock and had only just finished.\"(从更早一直做:过去完成进行时)","options":["had been working","are working","work","worked"],"answer_index":0,"stem_cn":"两个店员从八点起就一直忙着,刚刚才弄完。","explanation_cn":"“从八点起一直忙、直到刚刚才弄完”强调从更早持续下来的动作,用过去完成进行时 had been + doing。✓ they had been working since eight. ✗ worked:讲不出“一直持续”;✗ are working / work:时态不对。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp5','choice','{"stem":"\"The necklaces ___ beautifully on black velvet before the shop opened.\"(更早、且被动:过去完成被动)","options":["were arranging","arranged","arrange","had been arranged"],"answer_index":3,"stem_cn":"开店前,项链就已漂亮地摆在黑天鹅绒上。","explanation_cn":"项链是“被摆好”的(被动),而且发生在“开店”之前,用过去完成被动 had been + 过去分词。✓ the necklaces had been arranged. ✗ arranged:主动、分不出更早;✗ were arranging / arrange:时态或语态不对。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp6','choice','{"stem":"\"The soft black cloth under the jewelry was ___.\"(“天鹅绒、丝绒”用哪个词)","options":["metal","velvet","paper","cotton"],"answer_index":1,"stem_cn":"珠宝下面那块柔软的黑布是天鹅绒。","explanation_cn":"柔软、有光泽、常用来衬珠宝的布是 velvet(天鹅绒、丝绒)。✓ black velvet. ✗ cotton 棉布;✗ paper 纸;✗ metal 金属——都不对。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp6','choice','{"stem":"\"The car drove away at a ___ speed — unbelievably fast.\"(“极大的、惊人的”用哪个词)","options":["fantastic","normal","gentle","slow"],"answer_index":0,"stem_cn":"那辆车以惊人的速度开走,快得难以置信。","explanation_cn":"这里 fantastic 指“极大的、惊人的”,fantastic speed = 快得惊人。✓ at a fantastic speed. ✗ slow 慢的;✗ normal 普通的;✗ gentle 温和的——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp6','choice','{"stem":"\"A covered street with shops on both sides is called an ___.\"(“有拱廊的商业街”用哪个词)","options":["ocean","arcade","forest","farm"],"answer_index":1,"stem_cn":"两旁开着店铺的有顶盖的街叫拱廊街。","explanation_cn":"两旁开着店铺、有顶盖的商业街叫 arcade(拱廊街)。✓ a famous arcade. ✗ ocean 海洋;✗ forest 森林;✗ farm 农场——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',5,'am3_l06_gp6','choice','{"stem":"\"At night, drivers turn on their ___ to see the road.\"(“(汽车)前灯”用哪个词)","options":["mirrors","seats","keys","headlights"],"answer_index":3,"stem_cn":"夜里司机打开前灯照路。","explanation_cn":"汽车前部照路的灯是 headlights(前灯)。✓ turn on their headlights. ✗ mirrors 后视镜;✗ seats 座位;✗ keys 钥匙——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',6,NULL,'choice','{"stem":"美语里\"珠宝\"拼作:","options":["jewel-box","gem-stone","jewelry","jewellery"],"answer_index":2,"explanation_cn":"美语里“珠宝”拼作 jewelry(英式拼 jewellery)。✓ a jewelry shop 珠宝店。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',6,NULL,'choice','{"stem":"velvet 的意思是:","options":["皮革","棉布","塑料","天鹅绒,丝绒"],"answer_index":3,"explanation_cn":"velvet = 天鹅绒、丝绒(一种柔软有光泽的布)。✓ black velvet 黑色天鹅绒。\n顺带记:棉布 = cotton;皮革 = leather;塑料 = plastic."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',6,NULL,'choice','{"stem":"raid 的意思是:","options":["展览","派对","突袭,袭击","会议"],"answer_index":2,"explanation_cn":"raid = 突袭、突然的袭击(本课里是电影在拍这种场面)。✓ a raid was happening 好像发生了突袭。\n顺带记:展览 = exhibition;派对 = party;会议 = meeting."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',6,NULL,'choice','{"stem":"fantastic(此处)的意思是:","options":["很普通的","极大的,惊人的","很小的","很慢的"],"answer_index":1,"explanation_cn":"fantastic 在这里指“极大的、惊人的”。✓ a fantastic speed 惊人的速度。\n顺带记:很小的 = tiny;很慢的 = slow;很普通的 = ordinary."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',6,NULL,'choice','{"stem":"\"impossible\" 的意思是:","options":["很可能的","必须的","很容易的","不可能的"],"answer_index":3,"explanation_cn":"impossible = 不可能的(possible 加否定前缀 im-)。✓ It was impossible to stop them 要拦住他们不可能。\n顺带记:很可能的 = likely;很容易的 = easy;必须的 = necessary."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',6,NULL,'choice','{"stem":"arcade 的意思是:","options":["有拱廊的商业街","大海","森林","农场"],"answer_index":0,"explanation_cn":"arcade = 有拱廊、两旁开店的商业街。✓ a famous arcade 一条著名的拱廊街。\n顺带记:大海 = ocean;森林 = forest;农场 = farm."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',7,NULL,'cloze','{"stem":"第 1 空","context":"Early one morning, Mr. Taylor ___1___ his shiny new window display. His two assistants ___2___ since eight o''clock. Suddenly a loud car roared in, and two masked men ___3___ out and pretended to smash the window. It was ___4___ to calm Mr. Taylor until someone shouted that it was only a movie.","blank_no":1,"options":["admired","was admiring","admires","has admired"],"answer_index":1,"explanation_cn":"清早泰勒“正在欣赏”橱窗,是当背景的动作,用过去进行时。✓ Mr. Taylor was admiring his display."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',7,NULL,'cloze','{"stem":"第 2 空","context":"Early one morning, Mr. Taylor ___1___ his shiny new window display. His two assistants ___2___ since eight o''clock. Suddenly a loud car roared in, and two masked men ___3___ out and pretended to smash the window. It was ___4___ to calm Mr. Taylor until someone shouted that it was only a movie.","blank_no":2,"options":["had been working","work","are working","have worked"],"answer_index":0,"explanation_cn":"店员“从八点起一直忙”,强调从更早持续下来,用过去完成进行时。✓ his assistants had been working since eight."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',7,NULL,'cloze','{"stem":"第 3 空","context":"Early one morning, Mr. Taylor ___1___ his shiny new window display. His two assistants ___2___ since eight o''clock. Suddenly a loud car roared in, and two masked men ___3___ out and pretended to smash the window. It was ___4___ to calm Mr. Taylor until someone shouted that it was only a movie.","blank_no":3,"options":["were jumping","jumped","jump","have jumped"],"answer_index":1,"explanation_cn":"“蒙面人跳下车”是突然发生、完成的动作,用一般过去时。✓ two masked men jumped out."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',7,NULL,'cloze','{"stem":"第 4 空","context":"Early one morning, Mr. Taylor ___1___ his shiny new window display. His two assistants ___2___ since eight o''clock. Suddenly a loud car roared in, and two masked men ___3___ out and pretended to smash the window. It was ___4___ to calm Mr. Taylor until someone shouted that it was only a movie.","blank_no":4,"options":["impossible","possible","unpossible","dispossible"],"answer_index":0,"explanation_cn":"possible 的反义是 impossible(加 im-);“要让他冷静下来是不可能的”。✓ It was impossible to calm him."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',8,NULL,'choice','{"stem":"What was Mr. Taylor doing when the car roared in?","options":["Sleeping upstairs","Driving his car","Eating breakfast","Admiring his new window display"],"answer_index":3,"explanation_cn":"课文说 Mr. Taylor was admiring his new window display——车冲进来时,他正在欣赏新橱窗。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',8,NULL,'choice','{"stem":"What did Mr. Taylor and his staff throw out of the window?","options":["Chairs, ashtrays, and vases","Bags of money","Buckets of water","Diamond rings"],"answer_index":0,"explanation_cn":"课文说 he and his staff started throwing chairs, ashtrays, and vases out of the window——他们往外扔的是椅子、烟灰缸和花瓶。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',8,NULL,'choice','{"stem":"What was really going on in the arcade?","options":["A street market","A real robbery","A film was being made","A fire drill"],"answer_index":2,"explanation_cn":"课文说 it had all been part of a film——原来一切都是在拍电影。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',9,NULL,'choice','{"stem":"你想说\"我正看橱窗时,一辆车冲了进来\"(过去进行背景 + 一般过去打断):","options":["While I was looking at the window, a car rushed in.","While I am looking at the window, a car rushed in.","While I was looking at the window, a car was rush in.","While I looked at the window, a car was rushing in and out."],"answer_index":0,"explanation_cn":"“正看橱窗”是当背景的动作,用过去进行 was looking;“车冲进来”是打断的动作,用一般过去 rushed。✓ While I was looking at the window, a car rushed in. 场合:讲“我正做某事时,突然发生了另一件事”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',9,NULL,'choice','{"stem":"你想说\"要阻止他们是不可能的\"(possible 的反义 impossible):","options":["It was not possible impossible to stop them.","It was impossible to stop them.","It was unpossible to stop them.","It was impossibly to stop them."],"answer_index":1,"explanation_cn":"possible 的反义是 impossible(加否定前缀 im-)。✓ It was impossible to stop them. 场合:说“做某事根本不可能”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',9,NULL,'choice','{"stem":"你想说\"那辆车顶灯亮着、喇叭响着冲下来\"(with + 名词 + 分词,伴随状况):","options":["The car roared down with its lights are on and horn blares.","The car roared down with it lights on and horn blared.","The car roared down its lights on with horn blaring.","The car roared down with its lights on and its horn blaring."],"answer_index":3,"explanation_cn":"with + 名词 + 状态/分词,表示“某物怎样着”的伴随情况:灯亮着 with its lights on,喇叭响着 with its horn blaring。✓ 场合:一口气描述某物“……着、……着”地出现。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"arcade 的意思是:","options":["森林","农场","有拱廊的商业街","大海"],"answer_index":2,"explanation_cn":"arcade = 有拱廊、两旁开店的商业街。✓ a famous arcade."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"fantastic(此处)的意思是:","options":["极大的,惊人的","很普通的","很慢的","很小的"],"answer_index":0,"explanation_cn":"fantastic 在这里指“极大的、惊人的”。✓ a fantastic speed 惊人的速度。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"\"While the actors ___ the window, Mr. Taylor was upstairs.\"(持续的背景:过去进行)","options":["smashed","smash","have smashed","were smashing"],"answer_index":3,"stem_cn":"演员们正砸橱窗时,泰勒先生在楼上。","explanation_cn":"“泰勒在楼上”的同时,演员“正砸橱窗”是持续背景,主语复数,用过去进行 were + doing。✓ the actors were smashing the window. ✗ smashed / smash / have smashed:时态不对。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"\"His two assistants ___ since eight o''clock.\"(从更早一直做:过去完成进行时)","options":["are working","had been working","worked","work"],"answer_index":1,"stem_cn":"他的两个店员从八点起就一直在忙。","explanation_cn":"“从八点起一直忙”强调从更早持续下来,用过去完成进行时。✓ his assistants had been working since eight. ✗ worked / are working / work:讲不出“一直持续到现在之前”。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"\"come to a stop\" 的意思是:","options":["出发","加速","停下来","转弯"],"answer_index":2,"explanation_cn":"come to a stop = (车、人等)停下来。✓ The car came to a stop 车停了下来。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"\"at a fantastic speed\" 的意思是:","options":["小心地","准时地","以很慢的速度","以惊人的速度"],"answer_index":3,"explanation_cn":"at a fantastic speed = 以惊人的速度(飞快)。✓ It moved off at a fantastic speed 它飞快地开走了。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"Why did Mr. Taylor throw furniture out of the window?","options":["He wanted to sell the chairs","He thought a real robbery was happening","He was angry at his staff","He was cleaning his shop"],"answer_index":1,"passage":"The expensive shops in a famous outdoor arcade downtown were just opening. At this early hour, the arcade was almost empty. Mr. Taylor, who owned a jewelry shop, was admiring his new window display. His two assistants had been working busily since eight o''clock and had only just finished. Diamond necklaces and rings had been beautifully arranged on a background of black velvet. After gazing at the display for a few minutes, Mr. Taylor stepped back into his shop. The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade. It came to a stop right outside the jeweler''s. One man stayed at the wheel while two others, with masks over their faces, jumped out and began to smash the shop window with bright rubber bars. While this was going on, Mr. Taylor was upstairs, completely unaware that a film crew was hiding nearby. Sure that a raid was happening, he and his staff started throwing chairs, ashtrays, and vases out of the window. Furniture went flying into the arcade! The ''thieves'' scrambled back into the car, and it moved off at a fantastic speed. Just as it was leaving, Mr. Taylor rushed out, still throwing things, until a young woman waved her arms and shouted, ''Stop! It''s only a movie!'' The robbers were actors, the car was a prop, and it had all been part of a film. Poor Mr. Taylor turned red, for his brave ''rescue'' was now the funniest scene in the movie.","explanation_cn":"课文说 Sure that a raid was happening, he and his staff started throwing furniture——他以为真的在抢劫,才往外扔家具。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"How did the story really end?","options":["It was only a movie being filmed","The shop burned down","The thieves escaped with diamonds","The police caught everyone"],"answer_index":0,"passage":"The expensive shops in a famous outdoor arcade downtown were just opening. At this early hour, the arcade was almost empty. Mr. Taylor, who owned a jewelry shop, was admiring his new window display. His two assistants had been working busily since eight o''clock and had only just finished. Diamond necklaces and rings had been beautifully arranged on a background of black velvet. After gazing at the display for a few minutes, Mr. Taylor stepped back into his shop. The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade. It came to a stop right outside the jeweler''s. One man stayed at the wheel while two others, with masks over their faces, jumped out and began to smash the shop window with bright rubber bars. While this was going on, Mr. Taylor was upstairs, completely unaware that a film crew was hiding nearby. Sure that a raid was happening, he and his staff started throwing chairs, ashtrays, and vases out of the window. Furniture went flying into the arcade! The ''thieves'' scrambled back into the car, and it moved off at a fantastic speed. Just as it was leaving, Mr. Taylor rushed out, still throwing things, until a young woman waved her arms and shouted, ''Stop! It''s only a movie!'' The robbers were actors, the car was a prop, and it had all been part of a film. Poor Mr. Taylor turned red, for his brave ''rescue'' was now the funniest scene in the movie.","explanation_cn":"课文说 it had all been part of a film——原来一切只是在拍电影。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"What covered the men''s faces?","options":["Hats","Nothing at all","Silk scarves","Masks"],"answer_index":3,"audio":"The expensive shops in a famous outdoor arcade downtown were just opening. At this early hour, the arcade was almost empty. Mr. Taylor, who owned a jewelry shop, was admiring his new window display. His two assistants had been working busily since eight o''clock and had only just finished. Diamond necklaces and rings had been beautifully arranged on a background of black velvet. After gazing at the display for a few minutes, Mr. Taylor stepped back into his shop. The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade. It came to a stop right outside the jeweler''s. One man stayed at the wheel while two others, with masks over their faces, jumped out and began to smash the shop window with bright rubber bars. While this was going on, Mr. Taylor was upstairs, completely unaware that a film crew was hiding nearby. Sure that a raid was happening, he and his staff started throwing chairs, ashtrays, and vases out of the window. Furniture went flying into the arcade! The ''thieves'' scrambled back into the car, and it moved off at a fantastic speed. Just as it was leaving, Mr. Taylor rushed out, still throwing things, until a young woman waved her arms and shouted, ''Stop! It''s only a movie!'' The robbers were actors, the car was a prop, and it had all been part of a film. Poor Mr. Taylor turned red, for his brave ''rescue'' was now the funniest scene in the movie.","explanation_cn":"课文说 two others, with masks over their faces——那两个人脸上蒙着面罩。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l06',10,NULL,'choice','{"stem":"What did the young woman shout?","options":["That the police were coming","That the shop was on fire","That it was only a movie","That the car was hers"],"answer_index":2,"audio":"The expensive shops in a famous outdoor arcade downtown were just opening. At this early hour, the arcade was almost empty. Mr. Taylor, who owned a jewelry shop, was admiring his new window display. His two assistants had been working busily since eight o''clock and had only just finished. Diamond necklaces and rings had been beautifully arranged on a background of black velvet. After gazing at the display for a few minutes, Mr. Taylor stepped back into his shop. The silence was suddenly broken when a large car, with its headlights on and its horn blaring, roared down the arcade. It came to a stop right outside the jeweler''s. One man stayed at the wheel while two others, with masks over their faces, jumped out and began to smash the shop window with bright rubber bars. While this was going on, Mr. Taylor was upstairs, completely unaware that a film crew was hiding nearby. Sure that a raid was happening, he and his staff started throwing chairs, ashtrays, and vases out of the window. Furniture went flying into the arcade! The ''thieves'' scrambled back into the car, and it moved off at a fantastic speed. Just as it was leaving, Mr. Taylor rushed out, still throwing things, until a young woman waved her arms and shouted, ''Stop! It''s only a movie!'' The robbers were actors, the car was a prop, and it had all been part of a film. Poor Mr. Taylor turned red, for his brave ''rescue'' was now the funniest scene in the movie.","explanation_cn":"课文说 a young woman... shouted, ''Stop! It''s only a movie!''——年轻女子喊的是“这只是电影”。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am3_l07',3,2,7,'Cooked Cash','被煮熟的钞票','名词加后缀变形容词的构词法(success→successful、use→useless、care→careful/careless、fool→foolish、energy→energetic、danger→dangerous、luck→lucky),外加一般过去时叙事(承载官方KS)与现在完成的经历疑问(Has it ever happened? Have you ever...?)(原创承载 NCE3 L7 考点·美国残币赔付部门,面包师把三千美元藏微波炉被误烧成灰)','这种事碰到过你吗?有没有把一张二十美元的钞票落在牛仔裤兜里,然后一股脑丢进洗衣机?等你把裤子救出来,发现钞票已被洗得又白又软、成了一团糟?在美国犯这种错的人(而且不少)不必绝望。美国印钞局有个专门的部门叫“残币鉴别组”,专门处理那些把钱烧了、泡了、或喂了饿狗的人的索赔——看样子,狗特别爱把钱嚼个稀烂!最近有一桩案子:面包师 Carlos 和未婚妻 Maria 一起经营着一家红火的店。Carlos 有天生意特别好,为了妥善保管,把三千美元塞进了微波炉。后来 Maria 没留神,开微波炉热汤,结果打开炉门,只见钱变成了一小摞没用的灰!Carlos 把烧焦的残余寄给了那个部门。细心的专家把每一小片都查验了一遍,几周后他把钱如数拿了回来。“只要还剩下足够辨认的部分,我们就把钱退给大家,”一位女发言人解释道,“去年我们在成千上万宗索赔上赔付了数百万美元。”','{"q":"Listen and answer — Where did Carlos hide his money?","options":["In the microwave oven","Under his bed","In his dog''s bed","In a bank vault"],"answer_index":0}'::jsonb,'{"title":"名词变形容词:加后缀 + 讲过去","intro":"①很多形容词是由名词加后缀变来的:-ful(小心的 careful、有用的 useful)、-less(无用的 useless、粗心的 careless)、-ish(愚蠢的 foolish、孩子气的 childish)、-ic(精力充沛的 energetic、英雄的 heroic)、-ous(危险的 dangerous、出名的 famous)、-y(幸运的 lucky、健康的 healthy)。加哪个后缀多半要一个个记。②讲“发生了什么”用一般过去时(turned、mailed、got)。③问“有没有发生过、有没有做过”这类经历,用现在完成的疑问:Has it ever happened? / Have you ever...?","table":{"headers":["名词","加后缀→形容词","意思"],"rows":[["success / care","successful / careful / careless","成功的 / 小心的 / 粗心的"],["use / fool","useless / foolish","无用的 / 愚蠢的"],["energy / danger","energetic / dangerous","精力充沛的 / 危险的"],["luck / fame","lucky / famous","幸运的 / 出名的"]]},"specialRules":[{"rule":"-ful 表示“充满、有”(hopeful),-less 表示“没有”(hopeless);同一名词常能配不同后缀,意思相反:careful 小心的 vs careless 粗心的。","mark":"-ful / -less"},{"rule":"有些名词变形容词还会改拼写:energy→energetic、fame→famous、luck→lucky、beauty→beautiful。要连拼写一起记。","mark":"energy→energetic"},{"rule":"美语里“钞票”常说 bill(英式 note);“裤子”说 pants(英式 trousers)。本课已按美语写。","mark":"bill / pants"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l07',1,NULL,'Has it ever happened to you? Have you ever left a twenty-dollar bill in your jeans and then tossed them into the washing machine? When you rescued your jeans, did you find the bill washed to a pale, soggy mess?','这种事碰到过你吗?有没有把一张二十美元的钞票落在牛仔裤兜里,然后一股脑丢进洗衣机?等你把裤子救出来,发现钞票已被洗得又白又软、成了一团糟?') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l07',2,NULL,'Americans who make mistakes like this — and plenty do — need not despair. The U.S. Bureau of Engraving and Printing has a special office, the Mutilated Currency Division, that handles claims from people who have burned, soaked, or fed their money to a hungry dog. Dogs, it seems, love to chew up cash!','在美国犯这种错的人(而且不少)不必绝望。美国印钞局有个专门部门叫“残币鉴别组”,专门处理那些把钱烧了、泡了、或喂了饿狗的人的索赔——看样子,狗特别爱把钱嚼个稀烂!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l07',3,NULL,'One recent case involved a baker named Carlos and his fiancée, Maria, who together run a successful shop. Carlos had a very good day and, for safekeeping, tucked three thousand dollars into the microwave oven.','最近有一桩案子:面包师 Carlos 和未婚妻 Maria 一起经营着一家红火的店。Carlos 有天生意特别好,为了妥善保管,把三千美元塞进了微波炉。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l07',4,NULL,'Later, without realizing it, Maria turned on the microwave to heat some soup. Imagine their dismay when they opened the door and found a neat stack of useless ash where the money had been!','后来 Maria 没留神,开微波炉热汤,结果打开炉门,只见钱变成了一小摞没用的灰!') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am3_l07',5,NULL,'Carlos mailed the burned remains to the Division. Careful experts examined every scrap, and a few weeks later he got all his money back. ''As long as there is enough left to identify, we return people''s money,'' a spokeswoman explained. ''Last year we paid out millions of dollars on thousands of claims.''','Carlos 把烧焦的残余寄给了那个部门。细心的专家把每一小片都查验了一遍,几周后他把钱如数拿了回来。“只要还剩下足够辨认的部分,我们就把钱退给大家,”一位女发言人解释道,“去年我们在成千上万宗索赔上赔付了数百万美元。”') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
